@Test
public void practice_relative_speed_outDegreeSmall() {
	int numVertices = 600;
	Set<Integer> keySet = new HashSet<Integer>();
	for (int i = 0; i < numVertices; i++) {
		keySet.add(i);
	}
	Graph<Integer> gAL = new AdjacencyListGraph<Integer>(keySet);
	Graph<Integer> gAM = new AdjacencyMatrixGraph<Integer>(keySet);
	// Add a sparse set of edges: each vertex has only 2 outgoing edges
	for (int i = 0; i < numVertices; i++) {
		gAL.addEdge(i, (i + 1) % numVertices);
		gAL.addEdge(i, (i + 2) % numVertices);
		gAM.addEdge(i, (i + 1) % numVertices);
		gAM.addEdge(i, (i + 2) % numVertices);
	}
	// Time outDegree calls on every vertex many times
	long startAL = System.currentTimeMillis();
	for (int rep = 0; rep < 5000; rep++) {
		for (int i = 0; i < numVertices; i++) {
			gAL.outDegree(i);
		}
	}
	long timeAL = System.currentTimeMillis() - startAL;
	long startAM = System.currentTimeMillis();
	for (int rep = 0; rep < 5000; rep++) {
		for (int i = 0; i < numVertices; i++) {
			gAM.outDegree(i);
		}
	}
	long timeAM = System.currentTimeMillis() - startAM;
	System.out.printf("Practice OutDegree speed: %4d ms AdjList, %4d ms AdjMatrix%n", timeAL, timeAM);
	// With sparse edges, AdjList outDegree should be much faster than AdjMatrix
	assertTrue(timeAM > 2 * timeAL);
	points += 1;
}

