@Test
public void practice_lazyIteration_predecessorCountMethod() {
	assertTrue(Core.speedTestsOn);
	int numVertices = 10000;
	Set<Integer> keySet = new HashSet<Integer>();
	for (int i = 0; i < numVertices; i++) {
		keySet.add(i);
	}
	AdjacencyMatrixGraph<Integer> g = new AdjacencyMatrixGraph<Integer>(keySet);
	for (int j = 1; j < numVertices; j++) {
		g.addEdge(j, 0);
	}
	// predecessorCount should use predecessorIterator internally, staying lazy per call
	assertEquals(numVertices - 1, g.predecessorCount(0));
	// Now verify the method is not secretly building an eager set: time 1000 partial iterations
	long startTime = System.currentTimeMillis();
	for (int i = 0; i < 1000; i++) {
		Iterator<Integer> it = g.predecessorIterator(0);
		it.next();
		it.next();
	}
	long endTime = System.currentTimeMillis();
	assertTrue(endTime - startTime < 50);
	points += 1;
}

