    BinarySearchTree<Integer> bst = new BinarySearchTree<>();
    bst.insert(10);
    bst.insert(5);
    bst.insert(15);
    assertEquals(5, (int) bst.removeMin());
    assertEquals("[10, 15]", bst.toString());
    points += 3;
}

@Test
public void practice_pruneLeaves_repeatedPruning() {
    BinarySearchTree<Integer> bst = new BinarySearchTree<>();
    bst.insert(10); bst.insert(5); bst.insert(15); bst.insert(3);
    bst.pruneLeaves();
    assertEquals("[5, 10, 15]", bst.toString());
    bst.pruneLeaves();
    assertEquals("[10]", bst.toString());
    bst.pruneLeaves();
    assertEquals("[]", bst.toString());
    points += 2;
}

@Test
public void practice_numDirectedTriangles_completeLargeAL() {
    int size = 150;
    int numTris = size * (size - 1) * (size - 2) / 3;
    HashSet<Integer> keys = new HashSet<Integer>();
    for (Integer i = 0; i < size; i++) {
        keys.add(i);
    }
    Graph<Integer> g = new AdjacencyListGraph<Integer>(keys);
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            g.addEdge(i, j);
            g.addEdge(j, i);
        }
    }
    long startTime = System.nanoTime();
    assertEquals(numTris, g.numDirectedTriangles());
    long endTime = System.nanoTime();
    String timeInMs = Long.toString((endTime - startTime) / 1000000);
    assertTrue(endTime - startTime <= 1000000000, timeInMs + " ms > 1000 ms is too slow");
    m1points.add(2 * Core.m1weight);
}

@Test
public void practice_size_countIsolatedVertices() {
	Set<String> vertices = new HashSet<>(Arrays.asList("A", "B", "C"));
	Graph<String> g = new AdjacencyListGraph<>(vertices);
	g.addEdge("A", "B");
	// "C" has no outgoing or incoming edges, so it is isolated
	assertEquals(1, g.countIsolatedVertices());
	points += 1;
}

