@Test
public void practice_numDirectedTriangles_simpleAL() {
    HashSet<String> keysThree = new HashSet<String>();
    keysThree.add("A");
    keysThree.add("B");
    keysThree.add("C");
    Graph<String> g3 = new AdjacencyListGraph<String>(keysThree);
    g3.addEdge("A", "B");
    g3.addEdge("B", "C");
    assertEquals(0, g3.numDirectedTriangles());
    g3.addEdge("C", "A");
    assertEquals(1, g3.numDirectedTriangles());
    g3.addEdge("B", "A");
    g3.addEdge("C", "B");
    assertEquals(1, g3.numDirectedTriangles());
    g3.addEdge("A", "C");
    assertEquals(2, g3.numDirectedTriangles());
    m1points.add(2 * Core.m1weight);
}

@Test
public void practice_rehashCount_zeroBeforeFirstRehash() {
    assertEquals(0, mHashSet.rehashCount());
    String[] preThreshold = { "hello", "hi", "caio", "hola", "shalom", "bonjour", "ni-hao", "aloha", "tere", "sveiki" };
    for (String s : preThreshold) mHashSet.add(s);
    assertEquals("rehashCount must still be 0 right at the threshold", 0, mHashSet.rehashCount());
    mHashSet.add("mulishani");
    assertEquals("rehashCount must be exactly 1 after the add that triggered growth", 1, mHashSet.rehashCount());
    sPoints += 1;
}

