    assertEquals(0, mHashSet.numCollidedEntries());
    sPoints += 1;
}

@Test
public void practice_iterator_twoElementsNotNull() {
	StringHashSet set = new StringHashSet();
	set.add("a");
	set.add("z");
	Iterator<String> iter = set.iterator();
	String first = iter.next();
	String second = iter.next();
	assertTrue(first != null && second != null && !first.equals(second));
	assertFalse(iter.hasNext());
	points += 1;
}

@Test
public void practice_toString_twoElements() {
	StringHashSet set = new StringHashSet();
	set.add("a");
	set.add("b");
	String result = set.toString();
	assertTrue("[a, b]".equals(result) || "[b, a]".equals(result));
	points += 1;
}

